/**
 * Protocol v2 framing for the R2 electrotactile runtime.
 *
 * Frame layout (all multi-byte integers little-endian):
 *   MAGIC(2) | VERSION(1) | OPCODE(1) | TXN_ID(4) | PAYLOAD_LEN(2) | PAYLOAD(N) | CRC16(2)
 *
 * - TXN_ID is generated by the host and echoed by every response.
 * - CRC16-CCITT (poly 0x1021, init 0xFFFF, no reflection, no final XOR)
 *   covers MAGIC..PAYLOAD and is appended little-endian.
 * - A decoder that hits a bad CRC or an unknown opcode skips one byte and
 *   resynchronises at the next MAGIC; it never guesses frame boundaries.
 * - This module is pure TypeScript with no DOM dependencies so its golden
 *   vectors can be shared verbatim with the RP2040 firmware tests.
 */

export const HAPTIC_PROTOCOL_VERSION = 1;
export const MAGIC_BYTE_0 = 0x52; // "R"
export const MAGIC_BYTE_1 = 0x32; // "2"

export const MAX_FRAME_LENGTH = 256;
export const MAX_PAYLOAD_LENGTH = 240;

/** Host -> device opcodes. */
export const Op = {
  HELLO: 0x01,
  GET_STATUS: 0x02,
  ARM: 0x03,
  SET_CALIBRATION: 0x04,
  START_CALIBRATION: 0x05,
  PREPARE_SAMPLE: 0x06,
  COMMIT_AFTER: 0x07,
  STOP: 0x08
} as const;

/** Device -> host opcodes. */
export const DeviceOp = {
  HELLO_ACK: 0x81,
  STATUS: 0x82,
  ARMED: 0x83,
  CALIBRATION_APPLIED: 0x84,
  CALIBRATION_STARTED: 0x85,
  PREPARED: 0x86,
  STARTED: 0x87,
  COMPLETE: 0x88,
  STOPPED: 0x89,
  ERROR: 0x8a
} as const;

/** Structured device error codes. */
export const ErrorCode = {
  BAD_CRC: 0x01,
  BAD_FRAME: 0x02,
  BAD_STATE: 0x03,
  NOT_ARMED: 0x04,
  UNKNOWN_SAMPLE: 0x05,
  SAMPLE_UNDEFINED: 0x06,
  INVALID_ELECTRODE_MAP: 0x07,
  INVALID_OUTPUT: 0x08,
  BUSY: 0x09,
  WATCHDOG_STOP: 0x0a,
  TIMEOUT: 0x0b
} as const;

export type Opcode = (typeof Op)[keyof typeof Op] | (typeof DeviceOp)[keyof typeof DeviceOp];
export type ErrorCodeValue = (typeof ErrorCode)[keyof typeof ErrorCode];

export const ERROR_CODE_NAMES: Record<number, string> = {
  [ErrorCode.BAD_CRC]: "BAD_CRC",
  [ErrorCode.BAD_FRAME]: "BAD_FRAME",
  [ErrorCode.BAD_STATE]: "BAD_STATE",
  [ErrorCode.NOT_ARMED]: "NOT_ARMED",
  [ErrorCode.UNKNOWN_SAMPLE]: "UNKNOWN_SAMPLE",
  [ErrorCode.SAMPLE_UNDEFINED]: "SAMPLE_UNDEFINED",
  [ErrorCode.INVALID_ELECTRODE_MAP]: "INVALID_ELECTRODE_MAP",
  [ErrorCode.INVALID_OUTPUT]: "INVALID_OUTPUT",
  [ErrorCode.BUSY]: "BUSY",
  [ErrorCode.WATCHDOG_STOP]: "WATCHDOG_STOP",
  [ErrorCode.TIMEOUT]: "TIMEOUT"
};

const OPCODE_NAMES: Record<number, string> = {
  [Op.HELLO]: "HELLO",
  [Op.GET_STATUS]: "GET_STATUS",
  [Op.ARM]: "ARM",
  [Op.SET_CALIBRATION]: "SET_CALIBRATION",
  [Op.START_CALIBRATION]: "START_CALIBRATION",
  [Op.PREPARE_SAMPLE]: "PREPARE_SAMPLE",
  [Op.COMMIT_AFTER]: "COMMIT_AFTER",
  [Op.STOP]: "STOP",
  [DeviceOp.HELLO_ACK]: "HELLO_ACK",
  [DeviceOp.STATUS]: "STATUS",
  [DeviceOp.ARMED]: "ARMED",
  [DeviceOp.CALIBRATION_APPLIED]: "CALIBRATION_APPLIED",
  [DeviceOp.CALIBRATION_STARTED]: "CALIBRATION_STARTED",
  [DeviceOp.PREPARED]: "PREPARED",
  [DeviceOp.STARTED]: "STARTED",
  [DeviceOp.COMPLETE]: "COMPLETE",
  [DeviceOp.STOPPED]: "STOPPED",
  [DeviceOp.ERROR]: "ERROR"
};

export function opcodeName(opcode: number): string {
  return OPCODE_NAMES[opcode] ?? `UNKNOWN(0x${opcode.toString(16)})`;
}

// ---------------- CRC16-CCITT ----------------

const CRC_TABLE = (() => {
  const table = new Uint16Array(256);
  for (let i = 0; i < 256; i++) {
    let crc = i << 8;
    for (let bit = 0; bit < 8; bit++) {
      crc = (crc & 0x8000) !== 0 ? ((crc << 1) ^ 0x1021) & 0xffff : (crc << 1) & 0xffff;
    }
    table[i] = crc;
  }
  return table;
})();

export function crc16Ccitt(bytes: Uint8Array): number {
  let crc = 0xffff;
  for (const byte of bytes) {
    crc = ((crc << 8) ^ CRC_TABLE[((crc >> 8) ^ byte) & 0xff]) & 0xffff;
  }
  return crc;
}

// ---------------- Encoding ----------------

export type Frame = {
  version: number;
  opcode: number;
  txnId: number;
  payload: Uint8Array;
};

export function encodeFrame(opcode: number, txnId: number, payload: Uint8Array = new Uint8Array(0)): Uint8Array {
  if (payload.length > MAX_PAYLOAD_LENGTH) throw new Error(`payload too long: ${payload.length}`);
  const frame = new Uint8Array(10 + payload.length + 2);
  frame[0] = MAGIC_BYTE_0;
  frame[1] = MAGIC_BYTE_1;
  frame[2] = HAPTIC_PROTOCOL_VERSION;
  frame[3] = opcode;
  new DataView(frame.buffer).setUint32(4, txnId >>> 0, true);
  new DataView(frame.buffer).setUint16(8, payload.length, true);
  frame.set(payload, 10);
  const crc = crc16Ccitt(frame.subarray(0, 10 + payload.length));
  new DataView(frame.buffer).setUint16(10 + payload.length, crc, true);
  return frame;
}

export function frameToHex(frame: Uint8Array): string {
  return Array.from(frame, byte => byte.toString(16).padStart(2, "0")).join(" ");
}

/** Text payloads: US-ASCII sample ids; non-ASCII bytes raise. */
export function encodeAscii(value: string): Uint8Array {
  const bytes = new Uint8Array(value.length);
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i);
    if (code > 0x7f) throw new Error(`non-ASCII byte in payload string: ${value}`);
    bytes[i] = code;
  }
  return bytes;
}

export function decodeAscii(bytes: Uint8Array): string {
  let out = "";
  for (const byte of bytes) out += String.fromCharCode(byte);
  return out;
}

// ---------------- Payload builders / parsers ----------------

export function payloadSetCalibration(regionId: number, voltageCode: number): Uint8Array {
  return new Uint8Array([regionId & 0xff, voltageCode & 0xff]);
}

export function payloadStartCalibration(regionId: number): Uint8Array {
  return new Uint8Array([regionId & 0xff]);
}

export function payloadPrepareSample(sampleId: string): Uint8Array {
  return encodeAscii(sampleId);
}

export function payloadCommitAfter(delayMs: number): Uint8Array {
  const payload = new Uint8Array(4);
  new DataView(payload.buffer).setUint32(0, delayMs >>> 0, true);
  return payload;
}

export type HelloAckInfo = {
  fwMajor: number;
  fwMinor: number;
  sampleTableVersion: number;
  dryRun: boolean;
};

export function parseHelloAck(payload: Uint8Array): HelloAckInfo {
  return {
    fwMajor: payload[0] ?? 0,
    fwMinor: payload[1] ?? 0,
    sampleTableVersion: payload[2] ?? 0,
    dryRun: ((payload[3] ?? 0) & 0x01) !== 0
  };
}

export type StatusInfo = {
  state: number;
  armed: boolean;
  voltageCode: number;
  preparedSample: string | null;
  fault: number;
};

export function parseStatus(payload: Uint8Array): StatusInfo {
  const state = payload[0] ?? 0;
  const armed = payload[1] === 1;
  const voltageCode = payload[2] ?? 0;
  const sampleLen = payload[3] ?? 0;
  const preparedSample = sampleLen > 0 ? decodeAscii(payload.subarray(4, 4 + sampleLen)) : null;
  const fault = payload[4 + sampleLen] ?? 0;
  return { state, armed, voltageCode, preparedSample, fault };
}

export type PreparedInfo = { sampleId: string; durationUs: number };

export function parsePrepared(payload: Uint8Array): PreparedInfo {
  // sampleId is the payload minus the trailing 4-byte duration.
  const sampleId = decodeAscii(payload.subarray(0, payload.length - 4));
  const durationUs = new DataView(payload.buffer, payload.byteOffset).getUint32(payload.length - 4, true);
  return { sampleId, durationUs };
}

export type StartedInfo = { deviceStartUs: number };

export function parseStarted(payload: Uint8Array): StartedInfo {
  return { deviceStartUs: new DataView(payload.buffer, payload.byteOffset).getUint32(0, true) };
}

export type CompleteInfo = { sampleId: string; elapsedUs: number };

export function parseComplete(payload: Uint8Array): CompleteInfo {
  const sampleId = decodeAscii(payload.subarray(0, payload.length - 4));
  const elapsedUs = new DataView(payload.buffer, payload.byteOffset).getUint32(payload.length - 4, true);
  return { sampleId, elapsedUs };
}

export type ErrorInfo = { errorCode: number; detail: string };

export function parseError(payload: Uint8Array): ErrorInfo {
  return {
    errorCode: payload[0] ?? 0,
    detail: decodeAscii(payload.subarray(1))
  };
}

// ---------------- Decoding (streaming, resynchronising) ----------------

export type DecodeEvent =
  | { kind: "frame"; frame: Frame }
  | { kind: "bad-crc" }
  | { kind: "unknown-opcode"; opcode: number; txnId: number };

export class FrameDecoder {
  private buffer: Uint8Array = new Uint8Array(0);
  private onEvent: (event: DecodeEvent) => void;

  constructor(onEvent: (event: DecodeEvent) => void) {
    this.onEvent = onEvent;
  }

  push(chunk: Uint8Array): void {
    this.buffer = concat(this.buffer, chunk);
    this.drain();
  }

  reset(): void {
    this.buffer = new Uint8Array(0);
  }

  private drain(): void {
    // Find a MAGIC candidate. A bad CRC or unknown opcode consumes one byte
    // and the scan restarts, so garbage never triggers a misparsed frame.
    while (this.buffer.length >= 10) {
      const magicIndex = findMagic(this.buffer);
      if (magicIndex < 0) {
        // Keep only a potential partial MAGIC tail (1 byte).
        this.buffer = this.buffer.subarray(Math.max(0, this.buffer.length - 1));
        return;
      }
      if (magicIndex > 0) this.buffer = this.buffer.subarray(magicIndex);
      const payloadLen = new DataView(this.buffer.buffer, this.buffer.byteOffset).getUint16(8, true);
      if (payloadLen > MAX_PAYLOAD_LENGTH) {
        this.buffer = this.buffer.subarray(1);
        this.onEvent({ kind: "bad-crc" });
        continue;
      }
      const totalLen = 10 + payloadLen + 2;
      if (this.buffer.length < totalLen) return; // wait for more bytes
      const crcIndex = 10 + payloadLen;
      const expectedCrc = new DataView(this.buffer.buffer, this.buffer.byteOffset).getUint16(crcIndex, true);
      const actualCrc = crc16Ccitt(this.buffer.subarray(0, crcIndex));
      if (expectedCrc !== actualCrc) {
        this.buffer = this.buffer.subarray(1);
        this.onEvent({ kind: "bad-crc" });
        continue;
      }
      const frame: Frame = {
        version: this.buffer[2],
        opcode: this.buffer[3],
        txnId: new DataView(this.buffer.buffer, this.buffer.byteOffset).getUint32(4, true),
        payload: this.buffer.slice(10, crcIndex)
      };
      this.buffer = this.buffer.subarray(totalLen);
      if (frame.version !== HAPTIC_PROTOCOL_VERSION || OPCODE_NAMES[frame.opcode] === undefined) {
        this.onEvent({ kind: "unknown-opcode", opcode: frame.opcode, txnId: frame.txnId });
        continue;
      }
      this.onEvent({ kind: "frame", frame });
    }
  }
}

function concat(a: Uint8Array, b: Uint8Array): Uint8Array {
  const out = new Uint8Array(a.length + b.length);
  out.set(a, 0);
  out.set(b, a.length);
  return out;
}

function findMagic(bytes: Uint8Array): number {
  for (let i = 0; i + 1 < bytes.length; i++) {
    if (bytes[i] === MAGIC_BYTE_0 && bytes[i + 1] === MAGIC_BYTE_1) return i;
  }
  return -1;
}
